package com.aistock.prediction.forecast;
import com.aistock.common.BusinessException;import com.aistock.prediction.modelcatalog.*;
import com.fasterxml.jackson.databind.*;
import java.time.*;import java.util.*;import java.math.*;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;
import org.springframework.http.HttpStatus;
import static com.aistock.prediction.forecast.ForecastRecords.*;
public final class ForecastService {
 private final ForecastRepository records;private final ModelRepository models;private final ForecastDependencies dependencies;private final ObjectMapper mapper;private final Clock clock;private final com.aistock.prediction.marketuse.PredictionMarketUseOwner uses;
 public ForecastService(ForecastRepository records,ModelRepository models,ForecastDependencies dependencies,ObjectMapper mapper,Clock clock){this(records,models,dependencies,mapper,clock,null);}
 public ForecastService(ForecastRepository records,ModelRepository models,ForecastDependencies dependencies,ObjectMapper mapper,Clock clock,com.aistock.prediction.marketuse.PredictionMarketUseOwner uses){this.uses=uses;this.records=records;this.models=models;this.dependencies=dependencies;this.mapper=mapper;this.clock=clock;}
 public ForecastRecords.Record create(UUID user,Input in){validate(in);var claim=records.claim(user,in,hash(in),()->models.locked(head->{var v=models.find(UUID.fromString(in.modelId()),false);if(!"PUBLISHED".equals(v.state()))throw ForecastRepository.error("MODEL_NOT_PUBLISHED",HttpStatus.CONFLICT);if(v.manifest().path("config").path("seq_len").asInt()!=60||v.manifest().path("config").path("pred_len").asInt()!=in.horizon()||!contains(v.manifest().path("instruments"),in.instrumentId()))throw ForecastRepository.error("MODEL_INPUT_INCOMPATIBLE",HttpStatus.CONFLICT);return v;}));if(!claim.execute())return claim.record();var id=claim.record().predictionId();try(var scope=uses==null?com.aistock.prediction.marketuse.MarketUseContext.empty():uses.acquire("FORECAST",id,1)){
 if(uses!=null&&uses.enabled("FORECAST"))records.marketUseInput(id,1);
 var model=mapper.treeToValue(claim.record().modelSnapshot(),ModelRecords.Version.class);var window=dependencies.prepare(in.instrumentId(),id);var raw=com.aistock.prediction.marketuse.MarketUseContext.expectedRaw();if(raw!=null&&!raw.equals(window.path("rawVersionId").asText()))throw com.aistock.prediction.marketuse.MarketUseClient.invalid();if(uses!=null&&uses.enabled("FORECAST"))records.marketUseInput(id,1);var result=dependencies.infer(model,window);verify(in.instrumentId(),model,window,result);var snapshot=mapper.createObjectNode().set("input",window);((com.fasterxml.jackson.databind.node.ObjectNode)snapshot).set("prediction",result);records.succeed(user,id,1,snapshot);}catch(BusinessException e){records.fail(user,id,1,safeCode(e.code()));}catch(Exception e){records.fail(user,id,1,"PREDICTION_EXECUTION_FAILED");}finally{if(uses!=null)uses.notifyCompleted("FORECAST",id,1);}return records.get(user,id);}
 private static boolean contains(JsonNode nodes,String value){if(!nodes.isArray())return false;for(var n:nodes)if(value.equals(n.asText()))return true;return false;}
 private void validate(Input in){if(in==null||!uuid(in.operationId())||!uuid(in.modelId())||in.instrumentId()==null||!in.instrumentId().matches("(SH|SZ)[0-9]{6}")||in.horizon()==null||in.horizon()!=5)throw ForecastRepository.error("PREDICTION_REQUEST_INVALID",HttpStatus.BAD_REQUEST);}
 static boolean uuid(String x){try{return x!=null&&UUID.fromString(x).toString().equals(x);}catch(IllegalArgumentException e){return false;}}
 private String hash(Input in){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((in.modelId()+"|"+in.instrumentId()+"|"+in.horizon()).getBytes(StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 static String safeCode(String code){return code!=null&&code.matches("[A-Z_]{1,80}")?code:"PREDICTION_EXECUTION_FAILED";}
 static void verify(String requestedStock,ModelRecords.Version model,JsonNode w,JsonNode r){try{
  if(w==null||!w.isObject()||!requestedStock.equals(w.path("instrumentId").asText())||r==null||!r.isObject()||!"FRESH".equals(w.path("freshness").asText())||!"FRESH".equals(r.path("freshness").asText())||!uuid(w.path("inputVersionId").asText())||!uuid(w.path("rawVersionId").asText())||!contains(model.manifest().path("instruments"),w.path("instrumentId").asText())||!r.path("formalInference").isBoolean()||!r.path("formalInference").asBoolean()||!r.path("validationOnly").isBoolean()||r.path("validationOnly").asBoolean()||!model.modelId().toString().equals(r.path("modelId").asText())||!model.artifactId().equals(r.path("artifactId").asText())||!model.manifestHash().equals(r.path("manifestHash").asText())||!model.checkpointHash().equals(r.path("checkpointHash").asText())||!r.path("publicationRevision").isIntegralNumber()||r.path("publicationRevision").asLong()!=model.revision())throw new IllegalArgumentException();
  for(String k:List.of("instrumentId","inputVersionId","rawVersionId","inputHash","calendarHash","originDate","originRawClose"))if(!w.path(k).isTextual()||!w.path(k).equals(r.path(k)))throw new IllegalArgumentException();
  for(String k:List.of("inputHash","rawContentHash","calendarHash"))if(!w.path(k).asText().matches("[a-f0-9]{64}"))throw new IllegalArgumentException();
  var points=r.path("points");var dates=w.path("targetDates");if(!points.isArray()||points.size()!=5||!dates.isArray()||dates.size()!=5)throw new IllegalArgumentException();var previous=LocalDate.parse(w.path("originDate").asText());var origin=number(w.path("originRawClose"));for(int i=0;i<5;i++){var point=points.get(i);var target=LocalDate.parse(point.path("targetDate").asText());if(!point.path("step").isIntegralNumber()||point.path("step").asInt()!=i+1||!target.isAfter(previous)||!dates.get(i).equals(point.path("targetDate")))throw new IllegalArgumentException();var ratio=number(point.path("ratio"));var price=number(point.path("referencePrice"));if(origin.multiply(ratio).setScale(6,RoundingMode.HALF_UP).compareTo(price)!=0)throw new IllegalArgumentException();previous=target;}
 }catch(RuntimeException e){throw ForecastRepository.error("PREDICTION_RESULT_INVALID",HttpStatus.SERVICE_UNAVAILABLE);}}
 static BigDecimal number(JsonNode n){if(!n.isTextual()||n.asText().length()>24||!n.asText().matches("[0-9]+(?:\\.[0-9]{1,12})?"))throw new IllegalArgumentException();var x=new BigDecimal(n.asText());if(x.signum()<=0)throw new IllegalArgumentException();return x;}
}
